# Clean re-run of the recompiler. XenonRecomp never deletes old output, so a run that
# produces fewer files leaves stale ppc_recomp.N.cpp files behind (duplicate symbols,
# calls to functions that no longer exist). This removes the old output first.
#   powershell -ExecutionPolicy Bypass -File tools\recomp.ps1
$ErrorActionPreference = 'Stop'
$root = Split-Path $PSScriptRoot -Parent
Set-Location $root

# Jump tables: XenonAnalyse output + the ones tools\find-extra-switches.ps1 recovers.
$merged = "config\pes13_switch_tables_all.toml"
"# Merged jump tables - generated by tools\recomp.ps1, do not edit." | Set-Content $merged -Encoding ascii
Get-Content config\pes13_switch_tables.toml | Add-Content $merged -Encoding ascii
if (Test-Path config\pes13_switch_tables_extra.toml) { Get-Content config\pes13_switch_tables_extra.toml | Add-Content $merged -Encoding ascii }

Get-ChildItem generated -File | Where-Object { $_.Name -ne '.keep' } | Remove-Item
& "tools\XenonRecomp\build\XenonRecomp\XenonRecomp.exe" "config\pes13.toml" "tools\XenonRecomp\XenonUtils\ppc_context.h" *> config\recomp.log
if ($LASTEXITCODE -ne 0) { throw "XenonRecomp failed (exit $LASTEXITCODE) - see config\recomp.log" }

$warnings = Get-Content config\recomp.log | Where-Object { $_ -notmatch 'Recompiling functions' -and $_.Trim() }
Write-Host ("XenonRecomp: {0} files, {1} warning lines (config\recomp.log)" -f (Get-ChildItem generated\ppc_recomp.*.cpp).Count, @($warnings).Count)
& "$PSScriptRoot\gen-imports.ps1"
